from fastapi import FastAPI

app = FastAPI()

MOVIES = [
    {"title": "Dune", "genre": "sci-fi", "rating": 8.5},
    {"title": "Heat", "genre": "crime", "rating": 8.2},
    {"title": "Amélie", "genre": "romance", "rating": 7.9},
]


@app.get("/movies")
def list_movies(genre: str | None = None, min_rating: float = 0.0):
    return [
        m for m in MOVIES
        if (genre is None or m["genre"] == genre)
        and m["rating"] >= min_rating
    ]

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()


class Task(BaseModel):
    id: int
    title: str
    done: bool = False


class TaskCreate(BaseModel):
    title: str


class TaskUpdate(BaseModel):
    title: str | None = None
    done: bool | None = None


tasks: dict[int, Task] = {}
next_id = 1


def get_task_or_404(task_id: int) -> Task:
    if task_id not in tasks:
        raise HTTPException(status_code=404, detail="task not found")
    return tasks[task_id]


@app.post("/tasks", status_code=201, response_model=Task)
def create_task(payload: TaskCreate):
    global next_id
    task = Task(id=next_id, title=payload.title)
    tasks[next_id] = task
    next_id += 1
    return task


@app.get("/tasks", response_model=list[Task])
def list_tasks(done: bool | None = None):
    return [t for t in tasks.values() if done is None or t.done == done]


@app.get("/tasks/{task_id}", response_model=Task)
def get_task(task_id: int):
    return get_task_or_404(task_id)


@app.patch("/tasks/{task_id}", response_model=Task)
def update_task(task_id: int, payload: TaskUpdate):
    task = get_task_or_404(task_id)
    updates = payload.model_dump(exclude_unset=True)
    updated = task.model_copy(update=updates)
    tasks[task_id] = updated
    return updated


@app.delete("/tasks/{task_id}", status_code=204)
def delete_task(task_id: int):
    get_task_or_404(task_id)
    del tasks[task_id]
    return None

